import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n, K, L = int(data[0]), int(data[1]), int(data[2])
    A = list(map(int, data[3:3 + n]))
    if K > L:
        K, L = L, K
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + A[i]
    NEG = -(1 << 60)
    M = n - L
    N1 = n - K
    SK = [P[i + K] - P[i] for i in range(N1 + 1)]
    SL = [P[j + L] - P[j] for j in range(M + 1)]
    OFF = L
    size = n + OFF + 1

    def build(vals):
        g = [NEG] * size
        g[OFF:OFF + M + 1] = vals
        return g

    def wmax(g, w):
        res = [NEG] * size
        dq = deque()
        for t in range(size):
            gt = g[t]
            while dq and g[dq[-1]] <= gt:
                dq.pop()
            dq.append(t)
            if dq[0] <= t - w:
                dq.popleft()
            if t >= w - 1:
                res[t - w + 1] = g[dq[0]]
        return res

    # K <= L. Fragment 1 = [i, i+K), fragment 2 = [j, j+L).
    w4 = wmax(build([SL[j] - 3 * P[j + L] for j in range(M + 1)]), K)      # j in [i-L+1, i+K-L]
    w1 = wmax(build(SL), L - K + 1)                                         # j in [i+K-L, i]
    w3 = wmax(build([SL[j] + 3 * P[j] for j in range(M + 1)]), K)          # j in [i, i+K-1]
    pm = SL[:]
    for j in range(1, M + 1):
        if pm[j - 1] > pm[j]:
            pm[j] = pm[j - 1]
    sm = SL[:]
    for j in range(M - 1, -1, -1):
        if sm[j + 1] > sm[j]:
            sm[j] = sm[j + 1]
    best = NEG
    for i in range(N1 + 1):
        sk = SK[i]
        v = sk + 3 * P[i] + w4[i + 1]
        if v > best:
            best = v
        v = w1[i + K] - 2 * sk
        if v > best:
            best = v
        v = sk - 3 * P[i + K] + w3[i + OFF]
        if v > best:
            best = v
        if i >= L:
            v = sk + pm[min(i - L, M)]
            if v > best:
                best = v
        if i + K <= M:
            v = sk + sm[i + K]
            if v > best:
                best = v
    print(best)

main()

